import type { ObstacleDescriptor } from '../courses/types';
import { basePoseOf, clonePose, isMovingObstacle } from './descriptor';
import { evaluateObstaclePose } from './motion';
import type {
  ObstacleBodyFactory,
  ObstacleBody,
  ObstacleInstance,
  ObstacleVisual,
  ObstacleVisualFactory,
} from './types';

const DEFAULT_MAX_DELTA_SECONDS = 0.25;

type MutableInstance = { -readonly [K in keyof ObstacleInstance]: ObstacleInstance[K] };

export interface ObstacleManagerOptions {
  /** Builds the renderable half; omit for headless simulation. */
  visuals?: ObstacleVisualFactory | null;
  /** Builds the physics half; omit for pure visual previews. */
  bodies?: ObstacleBodyFactory | null;
  /** Upper bound on a single update step, mirroring PhysicsWorld clamping. */
  maxDeltaSeconds?: number;
}

/**
 * Owns the lifecycle of every dynamic obstacle on a hole: descriptor in,
 * visual + collider out, deterministic `update(delta)` in between, and a
 * disposal path that leaves no Three.js or Rapier resources behind.
 */
export class ObstacleManager {
  private readonly instances = new Map<string, MutableInstance>();
  private readonly animated: MutableInstance[] = [];
  private readonly visualFactory: ObstacleVisualFactory | null;
  private readonly bodyFactory: ObstacleBodyFactory | null;
  private readonly maxDeltaSeconds: number;
  private disposedFlag = false;

  constructor(options: ObstacleManagerOptions = {}) {
    this.visualFactory = options.visuals ?? null;
    this.bodyFactory = options.bodies ?? null;
    const maxDelta = options.maxDeltaSeconds ?? DEFAULT_MAX_DELTA_SECONDS;
    this.maxDeltaSeconds = Number.isFinite(maxDelta) && maxDelta > 0 ? maxDelta : DEFAULT_MAX_DELTA_SECONDS;
  }

  get count(): number {
    return this.instances.size;
  }

  get movingCount(): number {
    return this.animated.length;
  }

  get disposed(): boolean {
    return this.disposedFlag;
  }

  has(id: string): boolean {
    return this.instances.has(id);
  }

  get(id: string): ObstacleInstance | null {
    return this.instances.get(id) ?? null;
  }

  list(): ObstacleInstance[] {
    return [...this.instances.values()];
  }

  add(descriptor: ObstacleDescriptor): ObstacleInstance {
    if (this.disposedFlag) throw new Error('ObstacleManager is disposed');
    if (!descriptor.id) throw new Error('Obstacle descriptor requires a non-empty id');
    if (this.instances.has(descriptor.id)) throw new Error(`Duplicate obstacle id: ${descriptor.id}`);

    let visual: ObstacleVisual | null = null;
    let body: ObstacleBody | null = null;
    try {
      visual = this.visualFactory ? this.visualFactory.create(descriptor) : null;
      body = this.bodyFactory ? this.bodyFactory.create(descriptor) : null;
    } catch (error) {
      visual?.dispose();
      body?.dispose();
      throw error;
    }

    const basePose = basePoseOf(descriptor.transform);
    const instance: MutableInstance = {
      id: descriptor.id,
      descriptor,
      basePose,
      pose: clonePose(basePose),
      enabled: descriptor.enabled ?? true,
      elapsedSeconds: 0,
      moving: isMovingObstacle(descriptor),
      visual,
      body,
    };

    applyPose(instance);
    applyEnabled(instance);
    this.instances.set(instance.id, instance);
    if (instance.moving) this.animated.push(instance);
    return instance;
  }

  addAll(descriptors: readonly ObstacleDescriptor[]): ObstacleInstance[] {
    return descriptors.map((descriptor) => this.add(descriptor));
  }

  setEnabled(id: string, enabled: boolean): boolean {
    const instance = this.instances.get(id);
    if (!instance || instance.enabled === enabled) return false;
    instance.enabled = enabled;
    applyEnabled(instance);
    return true;
  }

  remove(id: string): boolean {
    const instance = this.instances.get(id);
    if (!instance) return false;
    this.instances.delete(id);
    const index = this.animated.indexOf(instance);
    if (index >= 0) this.animated.splice(index, 1);
    instance.visual?.dispose();
    instance.body?.dispose();
    return true;
  }

  /** Advances moving obstacles; static and hazard obstacles cost nothing here. */
  update(deltaSeconds: number): void {
    if (this.disposedFlag || this.animated.length === 0) return;
    if (!Number.isFinite(deltaSeconds) || deltaSeconds <= 0) return;
    const step = Math.min(deltaSeconds, this.maxDeltaSeconds);
    for (const instance of this.animated) {
      if (!instance.enabled) continue;
      instance.elapsedSeconds += step;
      instance.pose = evaluateObstaclePose(instance.descriptor, instance.elapsedSeconds, instance.basePose);
      applyPose(instance);
    }
  }

  /** Rewinds every obstacle to its authored pose, e.g. when a hole restarts. */
  reset(): void {
    for (const instance of this.instances.values()) {
      instance.elapsedSeconds = 0;
      instance.pose = clonePose(instance.basePose);
      applyPose(instance);
    }
  }

  clear(): void {
    for (const instance of this.instances.values()) {
      instance.visual?.dispose();
      instance.body?.dispose();
    }
    this.instances.clear();
    this.animated.length = 0;
  }

  dispose(): void {
    this.clear();
    this.disposedFlag = true;
  }
}

function applyPose(instance: MutableInstance): void {
  instance.visual?.setPose(instance.pose);
  instance.body?.setPose(instance.pose);
}

function applyEnabled(instance: MutableInstance): void {
  instance.visual?.setEnabled(instance.enabled);
  instance.body?.setEnabled(instance.enabled);
}
